import{_ as i,o as e,c as t,a3 as o}from"./chunks/framework.D8u9WiMi.js";const m=JSON.parse('{"title":"十二号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/12.md","filePath":"listOfEvents/2026/march/12.md"}'),r={name:"listOfEvents/2026/march/12.md"};function a(p,l,n,s,c,_){return e(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="十二号的流水账" tabindex="-1">十二号的流水账 <a class="header-anchor" href="#十二号的流水账" aria-label="Permalink to &quot;十二号的流水账&quot;">​</a></h1><p>买了个小锅 想买咖啡，回家先看看，之前的咖啡过期了吗，没有就先喝完</p><p>下个月再买做饭用的调料吧，这周吃自助，下周吃腊肠，再下周再吃自助，可以考虑鑫善坊</p><p>吃完鑫善坊可以考虑买调料</p><ol><li><p>包装类</p><ol><li>int的包装类是Integer</li><li>char的包装类是Character</li></ol></li><li><p>集合类</p><ol><li>单列集合和双列集合</li><li>单列就是ArrayList,set</li><li>双列就是map</li><li>Collection是单列集合的祖宗接口 <ol><li>add 添加元素</li><li>remove 移除元素</li><li>removeIf 根据条件移除元素</li><li>claer 清空元素</li><li>contains 判断指定元素是否在集合中</li><li>isEmpty 判断集合是否为空</li><li>size 获取集合的长度</li></ol></li></ol></li><li><p>常用类</p><ol><li>String <ol><li>new String(&quot;a&quot;) // 直接用&quot;&quot;引号创建</li><li>new String(char[])// 用字符数组创建，默认就是拼接</li><li>new String(byte[]) // 用字节数组创建，默认是字节码</li><li>String s = &quot;sss&quot;</li></ol></li><li>字符串的比较 <ol><li>==是只比较值，而引用数据类型，变量中存储的是引用地址</li><li>string可以用equals比较值</li><li>replace和replaceAll和js中用法一直</li></ol></li><li>StringBuilder 可以看做是个字符串的容器，和String不同的是可以更改 <ol><li>方法：append 添加，到尾部或者指定索引</li><li>reverse 反转字符串</li><li>.length() 获取字符串长度</li></ol></li></ol></li><li><p>枚举 一组常量的集合</p><ol><li><p>可以只有属性</p></li><li><p>也可以同时有键和值</p></li><li><p>枚举其实就是特殊的类</p></li><li><p>变量其实就是在加载的时候就调用有参构造创建的对象</p></li><li><p>枚举值也可以实现接口</p></li><li><p>实现接口时也可以重写方法</p></li></ol></li></ol>',5)])])}const u=i(r,[["render",a]]);export{m as __pageData,u as default};
